  await interruptSub.cancel();
  await taskSub.cancel();
  inboxTimer.cancel();
  // gh-2168: the run was aborted above — settle bounded, never wedged
  // (the SIGINT path's same bound; close order below is unchanged:
  // drain → usage fold → seal → exit).
  await waitForIdle();
  // Live-session presence off: the session stops being "running in
  // the CLI" for app viewers.
  await _extSessionEndBounded();
  if (_livePresence != null) {
    await _livePresence!.store.unregister(_livePresence!.sessionId);
    _livePresence = null;
  }
  // Lease bookkeeping: release OUR lease (graceful exit, #428); a
  // viewer never touches the owner's lease.
  await _releaseSessionLease();
  // herdr pane registration (issue #1481): released exactly once, real
  // quit only — awaited so process exit cannot cut the report.
  await _herdrRelease();
  // A session nobody wrote to leaves no file behind (never a viewer's
  // call — the owner's file is not ours to delete).
  if (_viewer == null) await deleteSessionIfEmpty();
  // gh-1241: close the usage segment AFTER the empty-session cleanup —
  // a deleted session has no chain to fold and no artifact should
  // outlive it.
  await _flushUsageLedger();
  // gh-1590: the REPL close flushes the coalesced job-board snapshot
  // and disarms the throttle's trailing leg — the last thing the
  // process does must never be a pending ledger write. The obligations
  // ledger and the subagent registry flush the same way.
  await _flushJobBoardPersist();
  await _flushObligationsLedger();
  await _subagentManager.flushPersist();
  // gh-2097: drain the diagnostic-append chain — a compaction post-
  // mortem must never lose its last lines to the process exit.
  await flushDiagnosticLog();
  // gh-1589 (REG-2): the REPL path seals with the SAME implementation
  // and the SAME close order as headless — drain → usage fold → seal →
  // exit. One invariant, both exits, no divergent variants.
  _sealSessionForExit();
}

